// Minimal endless runner
const canvas = document.getElementById('game');
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 200;

const GRAVITY = 0.6;
const PLAYER = {x:50, y:canvas.height-50, w:30, h:30, vy:0, jump:-12};
let obstacles = [];
let lastSpawn = 0;
let gameOver = false;
let score = 0;

function spawnObstacle() {
  const size = 20 + Math.random()*30;
  obstacles.push({x:canvas.width, y:canvas.height-size, w:size, h:size, speed:4});
}

function reset() {
  PLAYER.y = canvas.height-50;
  PLAYER.vy = 0;
  obstacles = [];
  lastSpawn = 0;
  gameOver = false;
  score = 0;
}

function update(dt) {
  if (gameOver) return;
  // player physics
  PLAYER.vy += GRAVITY;
  PLAYER.y += PLAYER.vy;
  if (PLAYER.y + PLAYER.h > canvas.height) {
    PLAYER.y = canvas.height - PLAYER.h;
    PLAYER.vy = 0;
  }
  // obstacles
  obstacles.forEach(o => o.x -= o.speed);
  obstacles = obstacles.filter(o => o.x + o.w > 0);
  // spawn
  lastSpawn += dt;
  if (lastSpawn > 1500) { // ms
    spawnObstacle();
    lastSpawn = 0;
  }
  // collision
  for (let o of obstacles) {
    if (PLAYER.x < o.x + o.w && PLAYER.x + PLAYER.w > o.x &&
        PLAYER.y < o.y + o.h && PLAYER.y + PLAYER.h > o.y) {
      gameOver = true;
      break;
    }
  }
  // score
  score += dt/1000;
}

function draw() {
  ctx.clearRect(0,0,canvas.width,canvas.height);
  // background
  ctx.fillStyle = '#eef';
  ctx.fillRect(0,0,canvas.width,canvas.height);
  // player
  ctx.fillStyle = '#07c';
  ctx.fillRect(PLAYER.x, PLAYER.y, PLAYER.w, PLAYER.h);
  // obstacles
  ctx.fillStyle = '#c00';
  obstacles.forEach(o => ctx.fillRect(o.x, o.y, o.w, o.h));
  // score / game over
  ctx.fillStyle = '#000';
  ctx.font = '16px sans-serif';
  ctx.fillText('Score: '+Math.floor(score), 10, 20);
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.5)';
    ctx.fillRect(0,0,canvas.width,canvas.height);
    ctx.fillStyle = '#fff';
    ctx.font = '30px sans-serif';
    ctx.fillText('Game Over', canvas.width/2-80, canvas.height/2);
  }
}

let lastTime = performance.now();
function loop(time) {
  const dt = time - lastTime;
  lastTime = time;
  update(dt);
  draw();
  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);

function jump() {
  if (PLAYER.vy===0 && PLAYER.y + PLAYER.h >= canvas.height) {
    PLAYER.vy = PLAYER.jump;
  }
}

window.addEventListener('keydown', e=>{if(e.code==='Space') jump();});
canvas.addEventListener('click', jump);
